#!/bin/sh
# Builds Smaragd Dash: graphics, caves and music are generated by the Python tools
# in tools/, the moves for the screencast by tools/solve.c; then everything is
# compiled into build/smaragd-dash.prg, which goes onto the disk image
# build/smaragd-dash.d81 together with the tiles (build/gen/tiles.bin as
# SMARAGD.TILES), the title logo (build/gen/logo.bin as SMARAGD.LOGO), the
# caves (build/caves/caveNN-L.bin as CAVENN-L: cave and level), the
# screencast's moves (demoNN.bin as DEMONN) and the high scores
# (SMARAGD.SCORES). The game loads them from that disk.
# Called by .vscode/run-current.sh with the compiler in $MEGA65_CC.

set -e
cd "$(dirname "$0")"
CC=${MEGA65_CC:-../toolchain/llvm-mos/bin/mos-mega65-clang}

# build/gen is compiled into the game, so nothing old may stay there
rm -rf build/gen build/caves
mkdir -p build/gen build/caves
python3 tools/mkgfx.py build/gen build/preview.png
python3 tools/mkcave.py build/caves build/gen caves/*.cave
python3 tools/mkmusic.py build/gen
# The moves for the screencast build (main.c, SCREENCAST), found with the
# engine itself on the host: build/caves/demoNN.bin, on the disk as DEMONN
${HOST_CC:-cc} -O2 -Wall -Isrc -Ibuild/caves -o build/solve tools/solve.c build/caves/caves.c
build/solve build/gen build/caves
# shellcheck disable=SC2086
"$CC" -Os -g -Wall $SMARAGD_CFLAGS -Isrc -Ibuild/gen -o build/smaragd-dash.prg \
    -Wl,-Map=build/smaragd-dash.map src/*.c build/gen/*.c
set --
for f in build/caves/*.bin; do
    set -- "$@" "$f=$(basename "$f" .bin)"
done
# The high score table: one sector of zeros, which the game reads as the
# default table and overwrites (src/hiscore.c); a new build keeps the one
# on the old disk.
head -c 254 /dev/zero > build/gen/scores.bin
../toolchain/tools/bin/mkd81.py --keep SMARAGD.SCORES build/smaragd-dash.d81 "SMARAGD DASH" \
    "build/smaragd-dash.prg=SMARAGD DASH" "build/gen/tiles.bin=SMARAGD.TILES" \
    "build/gen/logo.bin=SMARAGD.LOGO" \
    "build/gen/scores.bin=SMARAGD.SCORES" "$@"
